package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.client.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.*;import net.minecraft.core.BlockPos;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.Entity;import net.minecraft.world.phys.AABB;import com.mojang.blaze3d.pipeline.*;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import org.joml.Matrix4f;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class DvtClient {
 private static final UUID NONE=new UUID(0,0);private static Object world;private static final Map<BlockPos,DvtReply> STATES=new HashMap<>();private static final Map<BlockPos,Long> RECEIVED=new HashMap<>(),VISIBLE=new LinkedHashMap<>();private static final Map<UUID,Feed> FEEDS=new LinkedHashMap<>();private static boolean rendering;private static int ticks;private static long failureLog;
 static CameraInterferenceClient.View interference;
 public static boolean capturing(){return rendering;}
 public static boolean visible(AABB box){var m=Minecraft.getInstance();var f=m.levelRenderer.getFrustum();return f==null||f.isVisible(box);}
 public static DvtReply state(BlockPos p){return STATES.get(p);}
 public static void receive(DvtReply r){var old=STATES.put(r.pos(),r);if(old!=null&&(old.cx()!=r.cx()||old.cz()!=r.cz())){var f=FEEDS.get(r.selected());if(f!=null){f.ready=false;f.frame=0;}}RECEIVED.put(r.pos(),System.nanoTime());if(!r.status().equals("LIVE")){var f=FEEDS.get(r.selected());if(f!=null){f.ready=false;f.state=r;f.frame=0;}}regions();if(Minecraft.getInstance().screen instanceof DvtScreen screen&&screen.pos.equals(r.pos()))screen.updateChoices(r);if(r.show())Minecraft.getInstance().setScreen(new DvtScreen(r.pos()));}
 private static void regions(){var wanted=new HashSet<Long>();for(var e:STATES.entrySet())if(VISIBLE.containsKey(e.getKey())&&e.getValue().status().equals("LIVE")&&System.nanoTime()-RECEIVED.getOrDefault(e.getKey(),0L)<2_000_000_000L){var r=e.getValue();wanted.addAll(DroneChunkGeometry.square(r.cx(),r.cz(),2));}DvtChunks.regions(wanted);}
 public static void request(BlockPos p,int action,UUID drone,String player){AddonNetwork.dvtRequest(new DvtRequest(p,action,drone,player));}
 public static void watch(BlockPos p){if(!rendering)VISIBLE.put(p.immutable(),System.nanoTime());}
 public static ResourceLocation surface(Dvt01BlockEntity b){watch(b.getBlockPos());var r=STATES.get(b.getBlockPos());var f=feed(r);return f==null?null:f.texture;}
 public static Feed feed(DvtReply r){UUID key=r==null||r.selected()==null?NONE:r.selected();Feed f=FEEDS.get(key);if(f==null){if(!key.equals(NONE)&&FEEDS.keySet().stream().filter(k->!k.equals(NONE)).count()>=DvtConfig.FEEDS.get())return null;f=new Feed(key);FEEDS.put(key,f);}f.used=System.nanoTime();f.state=r;return f;}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){var m=Minecraft.getInstance();if(world!=m.level||m.player==null){clear();world=m.level;return;}ticks++;long now=System.nanoTime();var it=VISIBLE.entrySet().iterator();while(it.hasNext()){var v=it.next();if(now-v.getValue()>1_000_000_000L||!(m.level.getBlockEntity(v.getKey())instanceof Dvt01BlockEntity b)||!b.open){request(v.getKey(),6,null,"");it.remove();STATES.remove(v.getKey());RECEIVED.remove(v.getKey());}else if(ticks%10==0)request(v.getKey(),0,null,"");}regions();var fi=FEEDS.values().iterator();while(fi.hasNext()){var f=fi.next();if(now-f.used>2_000_000_000L){f.close();fi.remove();}}}
 @net.neoforged.bus.api.SubscribeEvent public static void render(net.neoforged.neoforge.client.event.RenderFrameEvent.Pre e){if(rendering||Minecraft.getInstance().level==null)return;long now=System.nanoTime();for(var f:FEEDS.values())if(demanded(f)&&now-f.used<1_000_000_000L&&now-f.frame>=1_000_000_000L/DvtConfig.FPS.get()){f.frame=now;f.state=bestState(f);f.capture(e.getPartialTick().getGameTimeDeltaPartialTick(false));}}
 private static DvtReply bestState(Feed f){var m=Minecraft.getInstance();DvtReply best=f.state;for(var pos:VISIBLE.keySet())if(m.level!=null&&m.level.getBlockEntity(pos)instanceof Dvt01BlockEntity b&&b.open){var r=STATES.get(pos);UUID id=r==null||r.selected()==null?NONE:r.selected();if(id.equals(f.id)){best=r;if(r!=null&&r.status().equals("LIVE"))return r;}}return best;}
 private static boolean demanded(Feed f){var m=Minecraft.getInstance();for(var pos:VISIBLE.keySet())if(m.level!=null&&m.level.getBlockEntity(pos)instanceof Dvt01BlockEntity b&&b.open){var r=STATES.get(pos);UUID id=r==null||r.selected()==null?NONE:r.selected();if(id.equals(f.id))return true;}return false;}
 public static void dirty(int x,int y,int z,boolean whole){var m=Minecraft.getInstance();if(m.level==null)return;for(var f:FEEDS.values())if(f.renderer!=null){if(whole){for(int sy=m.level.getMinSection();sy<m.level.getMaxSection();sy++)f.renderer.setSectionDirtyWithNeighbors(x,sy,z);}else f.renderer.setSectionDirtyWithNeighbors(x,y,z);}}
 public static boolean ownsTarget(RenderTarget target){for(var f:FEEDS.values())if(f.target==target)return true;return false;}
 public static int feedCount(){return FEEDS.size();}
 public static void clear(){for(var f:FEEDS.values())f.close();FEEDS.clear();STATES.clear();RECEIVED.clear();VISIBLE.clear();DvtChunks.clear();interference=null;}
 static final class ExternalTexture extends AbstractTexture{ExternalTexture(int id){this.id=id;}@Override public void load(net.minecraft.server.packs.resources.ResourceManager r){}@Override public void close(){this.id=-1;}@Override public void releaseId(){this.id=-1;}}
 public static final class Feed implements AutoCloseable{
  final UUID id;final ResourceLocation texture;RenderTarget target;LevelRenderer renderer;long used,frame;public boolean ready;DvtReply state;public String label="CONNECTING";CameraInterferenceClient.View noise;
  Feed(UUID id){this.id=id;texture=ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,"dvt/feed/"+id);ensure();}
  void ensure(){int w=DvtConfig.WIDTH.get(),h=w*9/16;if(target!=null&&target.width==w&&target.height==h)return;try(var saved=new WhiteHotState()){if(target!=null)destroyTarget();target=new TextureTarget(w,h,true,Minecraft.ON_OSX);target.setClearColor(.005f,.012f,.014f,1);target.clear(Minecraft.ON_OSX);Minecraft.getInstance().getTextureManager().register(texture,new ExternalTexture(target.getColorTextureId()));ready=false;}}
  void capture(float partial){
   var m=Minecraft.getInstance();if(m.level==null||m.player==null||m.gameMode==null||m.getOverlay()!=null)return;ensure();DvtReply s=state;String status=s==null?"CONNECTING":s.status();Entity drone=s==null?null:m.level.getEntity(s.entity());if(s!=null&&System.nanoTime()-RECEIVED.getOrDefault(s.pos(),0L)>2_000_000_000L)status="SIGNAL LOST";
   boolean live=status.equals("LIVE")&&drone!=null&&id.equals(drone.getUUID())&&drone.isAlive()&&m.level.getChunkSource().getChunk(drone.chunkPosition().x,drone.chunkPosition().z,net.minecraft.world.level.chunk.status.ChunkStatus.FULL,false)!=null;if(status.equals("LIVE")&&!live)status="CONNECTING";
   var hit=m.hitResult;var picked=m.crosshairPickEntity;var glState=new WhiteHotState();RenderTarget previous=m.getMainRenderTarget();Entity camera=m.getCameraEntity();CameraType cameraType=m.options.getCameraType();LevelRenderer levelRenderer=m.levelRenderer;var flags=(nl.smartstreamlabs.sbwdroneconfig.mixin.DvtGameRenderAccess)m.gameRenderer;var post=flags.dvt$post();boolean hand=flags.dvt$hand(),outline=flags.dvt$outline();float distance=flags.dvt$distance();var mv=RenderSystem.getModelViewStack();rendering=true;PortableFpvDetectorRenderContext.beginOffscreenRender();mv.pushMatrix();mv.identity();RenderSystem.applyModelViewMatrix();RenderSystem.backupProjectionMatrix();
   try{
    flags.dvt$post(null);
    ((nl.smartstreamlabs.sbwdroneconfig.mixin.WhiteHotTargetAccessor)m).drone$setVideoTarget(target);target.clear(Minecraft.ON_OSX);target.bindWrite(true);RenderSystem.viewport(0,0,target.width,target.height);RenderSystem.disableScissor();
    if(live){
     if(renderer==null){renderer=new LevelRenderer(m,m.getEntityRenderDispatcher(),m.getBlockEntityRenderDispatcher(),m.renderBuffers());renderer.setLevel(m.level);}
     ((nl.smartstreamlabs.sbwdroneconfig.mixin.DvtRenderAccess)m).dvt$renderer(renderer);m.options.setCameraType(CameraType.FIRST_PERSON);((nl.smartstreamlabs.sbwdroneconfig.mixin.DvtRenderAccess)m).dvt$camera(drone);DroneClientViewContext.beginReadOnlyCameraIntercept(id);m.gameRenderer.setRenderHand(false);m.gameRenderer.setRenderBlockOutline(false);
     if(noise==null||noise.entity!=drone)noise=new CameraInterferenceClient.View(drone);noise.raw=s.jam();noise.before=noise.amount;noise.amount=InterferenceMath.smooth(noise.amount,InterferenceMath.strength(s.jam(),AddonConfig.overlayStartThreshold()),1d/DvtConfig.FPS.get());noise.lost=false;interference=noise;
     RenderSystem.enableDepthTest();RenderSystem.depthMask(true);RenderSystem.disableBlend();target.bindWrite(true);m.gameRenderer.renderLevel(m.getTimer());m.renderBuffers().bufferSource().endBatch();m.renderBuffers().crumblingBufferSource().endBatch();
    }
    ready=live;label=status;paint(status,s,live);opaque();
   }catch(RuntimeException ex){ready=false;label="SIGNAL LOST";target.clear(Minecraft.ON_OSX);target.bindWrite(true);paint(label,s,false);opaque();if(System.nanoTime()-failureLog>5_000_000_000L){failureLog=System.nanoTime();SbwDroneRangeConfig.LOGGER.warn("DVT-01 feed failed; body camera restored",ex);}}
   finally{
    flags.dvt$post(post);interference=null;DroneClientViewContext.endReadOnlyCameraIntercept();((nl.smartstreamlabs.sbwdroneconfig.mixin.DvtRenderAccess)m).dvt$renderer(levelRenderer);((nl.smartstreamlabs.sbwdroneconfig.mixin.WhiteHotTargetAccessor)m).drone$setVideoTarget(previous);m.options.setCameraType(cameraType);((nl.smartstreamlabs.sbwdroneconfig.mixin.DvtRenderAccess)m).dvt$camera(camera==null?m.player:camera);m.gameRenderer.setRenderHand(hand);m.gameRenderer.setRenderBlockOutline(outline);flags.dvt$distance(distance);m.gameRenderer.getMainCamera().setup(m.level,m.getCameraEntity(),!cameraType.isFirstPerson(),cameraType.isMirrored(),partial);previous.bindWrite(true);RenderSystem.restoreProjectionMatrix();mv.popMatrix();RenderSystem.applyModelViewMatrix();RenderSystem.viewport(0,0,previous.width,previous.height);RenderSystem.disableScissor();RenderSystem.setShaderColor(1,1,1,1);RenderSystem.enableDepthTest();RenderSystem.disableBlend();PortableFpvDetectorRenderContext.endOffscreenRender();rendering=false;m.hitResult=hit;m.crosshairPickEntity=picked;glState.close();
   }
  }
  // Minecraft world passes may leave alpha at zero. The LCD is an opaque video surface.
  void opaque(){target.bindWrite(false);RenderSystem.disableScissor();RenderSystem.colorMask(false,false,false,true);org.lwjgl.opengl.GL30.glClearBufferfv(org.lwjgl.opengl.GL11.GL_COLOR,0,new float[]{0,0,0,1});RenderSystem.colorMask(true,true,true,true);}
  void paint(String status,DvtReply s,boolean live){
   var m=Minecraft.getInstance();RenderSystem.setProjectionMatrix(new Matrix4f().setOrtho(0,320,180,0,1000,21000),com.mojang.blaze3d.vertex.VertexSorting.ORTHOGRAPHIC_Z);var mv=RenderSystem.getModelViewStack();mv.identity();mv.translate(0,0,-11000f);RenderSystem.applyModelViewMatrix();var gui=new GuiGraphics(m,m.renderBuffers().bufferSource());int w=320,h=180;gui.fill(0,0,w,21,0xd0081115);gui.fill(0,h-20,w,h,0xd0081115);String name=s==null?"DVT-01":s.name().isBlank()?"DVT-01":s.name();gui.drawString(m.font,m.font.plainSubstrByWidth(name,w-m.font.width(status)-24),8,7,0xffd7e2df,false);gui.drawString(m.font,status,w-m.font.width(status)-8,7,live?0xffa8e4b3:0xffe7bc8c,false);if(!live)gui.drawCenteredString(m.font,status,w/2,h/2-4,0xffbecdca);if(s!=null){String battery=s.energy()<0||s.capacity()<=0?"BAT --":"BAT "+Math.round(100d*s.energy()/s.capacity())+"%";gui.drawString(m.font,battery+"   "+Math.round(s.distance())+" m",8,h-14,0xffd7e2df,false);}if(live&&s!=null&&m.level!=null&&m.level.getEntity(s.entity())instanceof Sd01Entity sd)gui.drawString(m.font,Sd01Client.depth(sd)+" / LIGHT "+(sd.lights()?"ON":"OFF"),105,h-14,0xffd7e2df,false);if(live&&s!=null&&m.level!=null)MoistureClient.draw(gui,m.level.getEntity(s.entity()),0,0,w,h);gui.flush();RenderSystem.enableDepthTest();
  }
  void destroyTarget(){Minecraft.getInstance().getTextureManager().release(texture);WhiteHotRender.releaseTarget(target);CameraInterferenceRender.releaseTarget(target);target.destroyBuffers();target=null;}
  public void close(){if(renderer!=null){renderer.setLevel(null);renderer.close();renderer=null;}if(target!=null)destroyTarget();}
 }
 static void draw(GuiGraphics g,Feed f,int x,int y,int w,int h){if(f==null)return;g.flush();try(var state=new WhiteHotState()){RenderSystem.disableDepthTest();RenderSystem.depthMask(false);RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();RenderSystem.setShader(GameRenderer::getPositionTexShader);RenderSystem.setShaderTexture(0,f.texture);RenderSystem.setShaderColor(1,1,1,1);var matrix=g.pose().last().pose();var b=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_TEX);b.addVertex(matrix,x,y+h,0).setUv(0,0);b.addVertex(matrix,x+w,y+h,0).setUv(1,0);b.addVertex(matrix,x+w,y,0).setUv(1,1);b.addVertex(matrix,x,y,0).setUv(0,1);BufferUploader.drawWithShader(b.buildOrThrow());}}
 private DvtClient(){}
}
